    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LB0LA [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 2] (StD, S0) ltac:(vm_compute; reflexivity)
