    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LB1RC [SCycL 2 0; SWin 4] (StC, S1) ltac:(vm_compute; reflexivity)
