    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LB1RD [SWin 3; SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
