(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1RD1LA_1LC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_1RD1LA_1LC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RB_1RD1LA_1LC1LA B0_0RB0LC_1LC1RB_1RD1LA_1LC1LA B1_0RB0LC_1LC1RB_1RD1LA_1LC1LA 4 13 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1LC1RB_1RD1LA_1LC1LA p j' E).
    + exact (geo_0RB0LC_1LC1RB_1RD1LA_1LC1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1LC1RB_1RD1LA_1LC1LA : stepn tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA 22 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA 22 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA 22 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LC_1LC1RB_1RD1LA_1LC1LA : existsb (fun tg => cfires tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA c0 22 tg) pins_0RB0LC_1LC1RB_1RD1LA_1LC1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_1RD1LA_1LC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_1RD1LA_1LC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_1RD1LA_1LC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_1RD1LA_1LC1LA : forall t, ~ In t pins_0RB0LC_1LC1RB_1RD1LA_1LC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 4] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 5] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1RD1LA_1LC1LA [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_0RB0LC_1LC1RB_1RD1LA_1LC1LA : NonHalt tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA /\ QHBoundTr 32779478 tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA /\ QuasiHaltsTr tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
Proof.
  apply (lap_qh_stage tmm_0RB0LC_1LC1RB_1RD1LA_1LC1LA pins_0RB0LC_1LC1RB_1RD1LA_1LC1LA Cc 1 22 32779478).
  - exact bootq_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
  - intros p _. apply lap_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_1RD1LA_1LC1LA. exact Ht.
  - exact wit_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
  - apply qcleb_QC_03. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_1RD1LA_1LC1LA : NonHalt tm_0RB0LC_1LC1RB_1RD1LA_1LC1LA /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_1RD1LA_1LC1LA /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_1RD1LA_1LC1LA.
Proof. apply (qh_triple_unmirror 32779478 tm_0RB0LC_1LC1RB_1RD1LA_1LC1LA). rewrite mirror_ok_0RB0LC_1LC1RB_1RD1LA_1LC1LA. exact qhtrm_0RB0LC_1LC1RB_1RD1LA_1LC1LA. Qed.

