(** 0RB0LC_1LC1RB_1RD1LA_1RB1LD *)
(** 0RB0LC_1LC1RB_1RD1LA_1RB1LD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_1RD1LA_1RB1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DL StD end.

(** Its mirror 0LB0RC_1RC1LB_1LD1RA_1LB1RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_1RD1LA_1RB1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_1RD1LA_1RB1LD : list Instr := [(StD, S1)].
Definition tmw_0RB0LC_1LC1RB_1RD1LA_1RB1LD : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_1RD1LA_1RB1LD pins_0RB0LC_1LC1RB_1RD1LA_1RB1LD.
