Lemma mirror_ok_0RB0LC_1LC1RB_1RD1LA_1RB1LD : mirror_tm tm_0RB0LC_1LC1RB_1RD1LA_1RB1LD = tmm_0RB0LC_1LC1RB_1RD1LA_1RB1LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

