  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1RC1RD_0RD1LA_1LC1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1RC1RD_0RD1LA_1LC1RD : stepn tmm_0RB0LC_1RC1RD_0RD1LA_1LC1RD 8 InitES = Some (lift (Cc 1)).
Proof.
