(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1RC1RD_0RD1LA_1LC1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1RC1RD_0RD1LA_1LC1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1RC1RD_0RD1LA_1LC1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1RC1RD_0RD1LA_1LC1RD : forall t, ~ In t pins_0RB0LC_1RC1RD_0RD1LA_1LC1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1RC1RD_0RD1LA_1LC1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LC_1RC1RD_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_0RB0LC_1RC1RD_0RD1LA_1LC1RD : NonHalt tmm_0RB0LC_1RC1RD_0RD1LA_1LC1RD /\ QHBoundTr 32779478 tmm_0RB0LC_1RC1RD_0RD1LA_1LC1RD /\ QuasiHaltsTr tmm_0RB0LC_1RC1RD_0RD1LA_1LC1RD.
Proof.
  apply (lap_qh_stage tmm_0RB0LC_1RC1RD_0RD1LA_1LC1RD pins_0RB0LC_1RC1RD_0RD1LA_1LC1RD Cc 1 8 32779478).
  - exact bootq_0RB0LC_1RC1RD_0RD1LA_1LC1RD.
