  - intros t Ht p _. apply fire_0RB0LC_1RC1RD_0RD1LA_1LC1RD. exact Ht.
  - exact wit_0RB0LC_1RC1RD_0RD1LA_1LC1RD.
  - apply qcleb_QC_03. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1RC1RD_0RD1LA_1LC1RD : NonHalt tm_0RB0LC_1RC1RD_0RD1LA_1LC1RD /\ QHBoundTr 32779478 tm_0RB0LC_1RC1RD_0RD1LA_1LC1RD /\ QuasiHaltsTr tm_0RB0LC_1RC1RD_0RD1LA_1LC1RD.
